\label{lem:one-path}
For every output prefix $k$, the boundary path and coefficients above
satisfy
\begin{equation}
 \mathrm{res}_k(v_\pi)=\sum_{u\in P(k)}\alpha_{u,k}\mathrm{err}_u.
 \label{eq:one-path}
\end{equation}

\label{thm:deterministic-main}
For every $T\ge2$, it holds that
\[
    \operatorname{OS}_{\det}(d,T) \in
    \begin{cases}
        O(\log T),&d=1,\\[2mm]
        O(\sqrt T),&d\ge2.
    \end{cases}
\]
These upper bounds hold against adaptive adversaries.

\label{prop:det-router}
For every stream of Euclidean unit-ball vectors, \cref{alg:tree-routing} with greedy signing of $(v_t,1)/\sqrt2$ satisfies
\begin{equation}
    \mathrm{res}_{\max}(v_\pi)
    \le \frac{\sqrt2+1}{1-\sqrt{2/3}}\sqrt T.
    \label{eq:det-router}
\end{equation}
This bound holds against adaptive adversaries and requires no
advance knowledge of the total.

\label{cor:aa-overview}
For every $T\ge2$, $d\ge1$, and $0<\delta<1$, \Cref{alg:tree-routing}
with the Aden-Ali signer uses $O(dT\log T)$ arithmetic operations and,
for every fixed Euclidean unit-ball stream, satisfies, with probability at least $1-\delta$,
\[
 \mathrm{res}_{\max}(v_\pi)
 \in O\left(\log T+
 \sqrt{\bigl(d+\log(1/\delta)\bigr)\log T}\right).
\]

\label{lem:stopped-tree}
For every $T\ge2$, $d\ge1$, and $0<\delta<1$, there is a randomized
router such that, for every fixed Euclidean unit-ball stream,
with probability at least $1-\delta$,
\begin{equation}\label{eq:stopped-tree}
 \mathrm{res}_{\max}(v_\pi)
 \in O\left(\min\Bigl\{\sqrt T,\;
 \log T+\sqrt{d_*\log(2+T/d_*)}
 +\sqrt{\log(2+T/d_*)\log(1/\delta)}\Bigr\}\right),
\end{equation}
where $d_*:=\min\{d,T\}$.
With the Aden-Ali signer, the running time is $O(dT\log T)$.
The same bound holds with the symmetrized Kulkarni--Reis--Rothvoss's signer, with a
different absolute constant and without the running-time guarantee.

\label{thm:random-lower-overview}
\label{lem:scalar-extraction}
\label{lem:scalar-tail}
\label{lem:det-lower-bound-higher-dim}
For $T\ge2$ and $d\ge1$, it holds that
\[
 \operatorname{OS}_{\det}(d,T)\in
 \begin{cases}
 \Omega(\log T),&d=1,\\
 \Omega(\sqrt T),&d\ge2,
 \end{cases}
\]
and, for $0<\delta\le1/2$ and $d_*:=\min\{d,T\}$,
\[
 \operatorname{OS}_{\rm rand}(d,T,\delta)
 \in \Omega\left(\log T+\sqrt{d_*\log(T/d_*)}\right).
\]
